-- Contest Scoreboard database setup, part 5 of 6: contestant titles, organisation isolation, sequential contest retention, and cross-organisation leaderboards.
-- Paste this WHOLE file into the Supabase SQL editor (New query) and press Run. Then do the next number.
-- Generated by scripts/build-setup-sql.sh from supabase/migrations. Do not edit by hand.
-- Safety check: stops with a plain message if a part was skipped or run twice.
do $$ begin
  if to_regclass('public.submissions') is null then
    raise exception 'The parts must be run in order. Start with part 1 (1-schema.sql): the tables do not exist yet.';
  end if;
end $$;
do $$ begin
  if to_regclass('public.login_failures') is null then
    raise exception 'Run part 4 (4-login-delay.sql) first.';
  end if;
end $$;
do $$ begin
  if exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'members' and column_name = 'title') then
    raise exception 'Part 5 was already run. Continue with part 6.';
  end if;
end $$;

-- ----- 20261009000500_member_title.sql -----
-- Contestant "title" (e.g. "HubSpot Specialist"): collected in the registration Form, synced by Apps Script,
-- shown to admins (the member leaderboard hides it: see the next migration). Optional; people who registered before this
-- existed simply have none.
--
-- The standings functions gain a column, which Postgres only allows by dropping and recreating them.

alter table members add column title text
  check (title is null or char_length(btrim(title)) between 1 and 80);

-- Store titles tidy: trimmed, and a blank title is no title.
create function trg_members_title() returns trigger
language plpgsql set search_path = pg_catalog as $$
begin
  new.title := nullif(btrim(new.title), '');
  return new;
end $$;
create trigger members_title_tidy before insert or update of title on members
  for each row execute function trg_members_title();

drop function get_leaderboard();
drop function get_admin_leaderboard();
drop function _standings(uuid);

create function _standings(p_contest uuid)
returns table (member_id uuid, email citext, display_name text, title text, active boolean, points int,
               tasks_completed int, reached_at timestamptz, pending_count int, rank int, ord int)
language sql stable security definer set search_path = public, pg_temp as $$
  with agg as (
    select m.id, m.email, m.display_name, m.title, m.active,
           coalesce(sum(s.points_awarded) filter (where s.status = 'approved'), 0)::int as pts,
           (count(*) filter (where s.status = 'approved'))::int as tasks,
           max(s.submitted_at) filter (where s.status = 'approved') as reached,
           (count(*) filter (where s.status = 'pending'))::int as pend
    from members m
    left join submissions s on s.member_id = m.id
    where m.contest_id = p_contest
    group by m.id
  )
  select a.id, a.email, a.display_name, a.title, a.active, a.pts, a.tasks, a.reached, a.pend,
         case when a.active and a.pts > 0 then
           (row_number() over (partition by (a.active and a.pts > 0)
                               order by a.pts desc, a.reached asc nulls last, lower(a.display_name)))::int
         end,
         (row_number() over (order by a.active desc, (a.pts > 0) desc, a.pts desc,
                             a.reached asc nulls last, lower(a.display_name)))::int
  from agg a
$$;

create function get_leaderboard()
returns table (display_name text, title text, points int, tasks_completed int, rank int, reached_at timestamptz, is_me boolean)
language plpgsql stable security definer set search_path = public, pg_temp as $$
#variable_conflict use_column
begin
  if not (is_member() or is_admin()) then
    raise exception 'forbidden: Login required.' using errcode = '42501';
  end if;
  return query
    select st.display_name, st.title, st.points, st.tasks_completed, st.rank, st.reached_at,
           (st.member_id = auth.uid())
    from _standings(current_contest_id()) st
    where st.active
    order by st.ord;
end $$;

create function get_admin_leaderboard()
returns table (member_id uuid, email citext, display_name text, title text, points int, tasks_completed int,
               rank int, reached_at timestamptz, pending_count int, active boolean)
language plpgsql stable security definer set search_path = public, pg_temp as $$
#variable_conflict use_column
begin
  perform _require_admin();
  return query
    select st.member_id, st.email, st.display_name, st.title, st.points, st.tasks_completed, st.rank,
           st.reached_at, st.pending_count, st.active
    from _standings(current_contest_id()) st
    order by st.ord;
end $$;

-- same access as before: nobody by default; signed-in users may call the two RPCs (they check the role inside)
revoke all on function _standings(uuid), get_leaderboard(), get_admin_leaderboard() from public, anon, authenticated;
grant execute on function _standings(uuid), get_leaderboard(), get_admin_leaderboard() to service_role;
grant execute on function get_leaderboard(), get_admin_leaderboard() to authenticated;

-- New functions are closed by default. (Postgres grants EXECUTE to PUBLIC on every new function unless
-- that default is revoked globally; the schema-level revoke in the security migration does not remove it.)
revoke all on function trg_members_title() from public, anon, authenticated;
alter default privileges revoke execute on functions from public;

-- ----- 20261009000600_leaderboard_hides_title.sql -----
-- Titles (Director, Senior Manager ...) are for organizers. The member leaderboard and the projector
-- board must not show them, so the function behind them stops returning the column at all.
-- Admins still get titles from get_admin_leaderboard(); a member can only ever read their own row of
-- `members` (their own title), never teammates'.

drop function get_leaderboard();

create function get_leaderboard()
returns table (display_name text, points int, tasks_completed int, rank int, reached_at timestamptz, is_me boolean)
language plpgsql stable security definer set search_path = public, pg_temp as $$
#variable_conflict use_column
begin
  if not (is_member() or is_admin()) then
    raise exception 'forbidden: Login required.' using errcode = '42501';
  end if;
  return query
    select st.display_name, st.points, st.tasks_completed, st.rank, st.reached_at,
           (st.member_id = auth.uid())
    from _standings(current_contest_id()) st
    where st.active
    order by st.ord;
end $$;

revoke all on function get_leaderboard() from public, anon, authenticated;
grant execute on function get_leaderboard() to service_role, authenticated;

-- ----- 20261024124552_leaderboard_category_counts.sql -----
-- Return the approved submission count for each active category on every leaderboard row.
-- The setup migrations create this function earlier, then the title migration replaces it.
drop function get_leaderboard();

create function get_leaderboard()
returns table (
  display_name text,
  points int,
  tasks_completed int,
  rank int,
  reached_at timestamptz,
  is_me boolean,
  category_counts jsonb
)
language plpgsql stable security definer set search_path = public, pg_temp as $$
#variable_conflict use_column
begin
  if not (is_member() or is_admin()) then
    raise exception 'forbidden: Login required.' using errcode = '42501';
  end if;
  return query
    select st.display_name, st.points, st.tasks_completed, st.rank, st.reached_at,
           (st.member_id = auth.uid()), coalesce(counts.by_category, '{}'::jsonb)
    from _standings(current_contest_id()) st
    left join lateral (
      select jsonb_object_agg(category_totals.category_id::text, category_totals.task_count
                              order by category_totals.sort_order) as by_category
      from (
        select c.id as category_id, c.sort_order, count(s.id)::int as task_count
        from categories c
        left join submissions s
          on s.contest_id = c.contest_id
         and s.category_id = c.id
         and s.member_id = st.member_id
         and s.status = 'approved'
        where c.contest_id = current_contest_id()
          and c.active
        group by c.id, c.sort_order
      ) category_totals
    ) counts on true
    where st.active
    order by st.ord;
end $$;

revoke all on function get_leaderboard() from public, anon, authenticated;
grant execute on function get_leaderboard() to service_role, authenticated;
-- ----- 20261024152538_organization_isolation.sql -----
-- Enforce tenant identity from the authenticated member/admin row, never from a global fallback.
-- The zero-argument helper is the only contest context exposed to application RPCs.
do $$
begin
  if exists (
    select 1
    from admins a
    join members m on m.id = a.id
    where a.organization_id is distinct from m.organization_id
  ) then
    raise exception 'Resolve Auth accounts assigned to multiple organisations before applying organisation isolation.';
  end if;
end $$;

create or replace function current_organization_id() returns uuid
language sql stable security definer set search_path = public, pg_temp as $$
  select coalesce(
    (select a.organization_id from admins a where a.id = auth.uid() and a.active),
    (select m.organization_id from members m where m.id = auth.uid() and m.active)
  )
$$;

create or replace function current_contest_id() returns uuid
language sql stable security definer set search_path = public, pg_temp as $$
  select c.id
  from contests c
  where c.organization_id = current_organization_id()
  order by c.created_at desc
  limit 1
$$;

create or replace function current_contest_id(p_org_id uuid) returns uuid
language sql stable security definer set search_path = public, pg_temp as $$
  select c.id
  from contests c
  where p_org_id = current_organization_id()
    and c.organization_id = p_org_id
  order by c.created_at desc
  limit 1
$$;

create or replace function is_org_admin(p_org_id uuid default current_organization_id()) returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select p_org_id = current_organization_id() and exists (
    select 1 from admins a
    where a.id = auth.uid() and a.active and a.organization_id = p_org_id
  )
$$;

create or replace function is_org_owner(p_org_id uuid default current_organization_id()) returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select p_org_id = current_organization_id() and exists (
    select 1 from admins a
    where a.id = auth.uid() and a.active and a.role = 'owner'
      and a.organization_id = p_org_id
  )
$$;

create or replace function is_admin() returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select exists (
    select 1 from admins a
    where a.id = auth.uid() and a.active
      and a.organization_id = current_organization_id()
  )
$$;

create or replace function is_owner() returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select exists (
    select 1 from admins a
    where a.id = auth.uid() and a.active and a.role = 'owner'
      and a.organization_id = current_organization_id()
  )
$$;

create or replace function is_member() returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select exists (
    select 1 from members m
    where m.id = auth.uid() and m.active
      and m.organization_id = current_organization_id()
      and m.contest_id = current_contest_id()
  )
$$;

-- Keep member registrations compatible with the Apps Script payload: the contest is the
-- authoritative source of the organisation, rather than a client-supplied tenant ID.
create function set_row_organization_from_contest() returns trigger
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_organization_id uuid;
begin
  select c.organization_id into v_organization_id
  from contests c
  where c.id = new.contest_id;

  if v_organization_id is null then
    raise exception 'contest_not_found: The selected contest does not exist.';
  end if;
  if new.organization_id is not null and new.organization_id <> v_organization_id then
    raise exception 'organization_mismatch: The row organisation must match its contest.';
  end if;

  new.organization_id := v_organization_id;
  return new;
end $$;

revoke all on function set_row_organization_from_contest() from public, anon, authenticated;

create trigger members_set_organization
before insert or update of contest_id, organization_id on members
for each row execute function set_row_organization_from_contest();

create trigger categories_set_organization
before insert or update of contest_id, organization_id on categories
for each row execute function set_row_organization_from_contest();

create trigger submissions_set_organization
before insert or update of contest_id, organization_id on submissions
for each row execute function set_row_organization_from_contest();

create function enforce_identity_organization() returns trigger
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_organization_id uuid;
begin
  if tg_table_name = 'members' then
    select a.organization_id into v_organization_id
    from admins a where a.id = new.id;
  else
    select m.organization_id into v_organization_id
    from members m where m.id = new.id;
  end if;

  if v_organization_id is not null and v_organization_id <> new.organization_id then
    raise exception 'identity_organization_conflict: An Auth account can belong to only one organisation.';
  end if;
  return new;
end $$;

revoke all on function enforce_identity_organization() from public, anon, authenticated;

create trigger members_validate_identity_organization
before insert or update of id, organization_id on members
for each row execute function enforce_identity_organization();

create trigger admins_validate_identity_organization
before insert or update of id, organization_id on admins
for each row execute function enforce_identity_organization();

create function set_audit_organization_from_contest() returns trigger
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_organization_id uuid;
begin
  if new.contest_id is null then
    select coalesce(
      (select a.organization_id from admins a where a.id = new.actor_id),
      (select m.organization_id from members m where m.id = new.actor_id),
      new.organization_id
    )
    into v_organization_id;

    if new.organization_id is not null
       and v_organization_id is not null
       and new.organization_id <> v_organization_id then
      raise exception 'organization_mismatch: The audit organisation must match its actor.';
    end if;

    new.organization_id := v_organization_id;
    return new;
  end if;

  select c.organization_id into v_organization_id
  from contests c
  where c.id = new.contest_id;

  if v_organization_id is null then
    raise exception 'contest_not_found: The audit contest does not exist.';
  end if;
  if new.organization_id is not null and new.organization_id <> v_organization_id then
    raise exception 'organization_mismatch: The audit organisation must match its contest.';
  end if;

  new.organization_id := v_organization_id;
  return new;
end $$;

revoke all on function set_audit_organization_from_contest() from public, anon, authenticated;

create trigger audit_log_set_organization
before insert or update of contest_id, organization_id on audit_log
for each row execute function set_audit_organization_from_contest();

-- Composite keys make cross-organisation/contest references impossible even for privileged
-- writers that bypass RLS, including submissions pointing at another tenant's member/category.
alter table contests add constraint contests_id_organization_uq unique (id, organization_id);
alter table members add constraint members_id_contest_organization_uq
  unique (id, contest_id, organization_id);
alter table categories add constraint categories_id_contest_organization_uq
  unique (id, contest_id, organization_id);
alter table submissions add constraint submissions_id_contest_organization_uq
  unique (id, contest_id, organization_id);

create index members_contest_organization_idx on members (contest_id, organization_id);
create index categories_contest_organization_idx on categories (contest_id, organization_id);
create index submissions_member_tenant_idx on submissions (member_id, contest_id, organization_id);
create index submissions_category_tenant_idx on submissions (category_id, contest_id, organization_id);
create index submissions_resubmission_tenant_idx on submissions (resubmission_of, contest_id, organization_id)
  where resubmission_of is not null;

alter table members add constraint members_contest_organization_fkey
  foreign key (contest_id, organization_id)
  references contests (id, organization_id) not valid;
alter table categories add constraint categories_contest_organization_fkey
  foreign key (contest_id, organization_id)
  references contests (id, organization_id) not valid;
alter table submissions add constraint submissions_contest_organization_fkey
  foreign key (contest_id, organization_id)
  references contests (id, organization_id) not valid;
alter table submissions add constraint submissions_member_tenant_fkey
  foreign key (member_id, contest_id, organization_id)
  references members (id, contest_id, organization_id) not valid;
alter table submissions add constraint submissions_category_tenant_fkey
  foreign key (category_id, contest_id, organization_id)
  references categories (id, contest_id, organization_id) not valid;
alter table submissions add constraint submissions_resubmission_tenant_fkey
  foreign key (resubmission_of, contest_id, organization_id)
  references submissions (id, contest_id, organization_id) not valid;

alter table members validate constraint members_contest_organization_fkey;
alter table categories validate constraint categories_contest_organization_fkey;
alter table submissions validate constraint submissions_contest_organization_fkey;
alter table submissions validate constraint submissions_member_tenant_fkey;
alter table submissions validate constraint submissions_category_tenant_fkey;
alter table submissions validate constraint submissions_resubmission_tenant_fkey;

-- Organisation-admin RPCs must only manage admins in the caller's own organisation.
create or replace function owner_add_admin(p_user uuid, p_email citext, p_role admin_role) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_organization_id uuid := current_organization_id();
begin
  perform _require_owner();
  if v_organization_id is null then
    raise exception 'forbidden: An organisation owner is required.';
  end if;
  perform _audit_ctx('admin.added', null);
  insert into admins (id, email, role, organization_id)
  values (p_user, p_email, p_role, v_organization_id);
end $$;

create or replace function owner_set_admin_active(p_id uuid, p_active boolean) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_organization_id uuid := current_organization_id();
begin
  perform _require_owner();
  if not exists (
    select 1 from admins where id = p_id and organization_id = v_organization_id
  ) then
    raise exception 'not_found: Admin not found.';
  end if;
  if not p_active and p_id = auth.uid() then
    raise exception 'self_remove: You cannot remove yourself.';
  end if;
  perform _audit_ctx(case when p_active then 'admin.reactivated' else 'admin.removed' end, null);
  update admins
  set active = p_active
  where id = p_id and organization_id = v_organization_id;
end $$;

-- RLS helpers must not make platform admins implicit members/admins of every contest.
create function is_platform_admin() returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select exists (
    select 1 from platform_admins pa where pa.id = auth.uid() and pa.active
  )
$$;

revoke all on function is_platform_admin() from public, anon, authenticated;
grant execute on function is_platform_admin() to authenticated, service_role;
grant execute on function current_organization_id(), current_contest_id(),
  current_contest_id(uuid), is_admin(), is_owner(), is_member(),
  is_org_admin(uuid), is_org_owner(uuid)
to authenticated, service_role;

-- Organisation metadata is visible only to its own signed-in users, except platform admins.
alter table organizations enable row level security;
alter table platform_admins enable row level security;
grant select on organizations to authenticated;
revoke all on platform_admins from public, anon, authenticated;

drop policy if exists contests_select on contests;
drop policy if exists members_select on members;
drop policy if exists admins_select on admins;
drop policy if exists categories_select on categories;
drop policy if exists submissions_select on submissions;
drop policy if exists audit_log_select on audit_log;
drop policy if exists organizations_select on organizations;

create policy organizations_select on organizations for select to authenticated
  using (id = current_organization_id() or is_platform_admin());

create policy contests_select on contests for select to authenticated
  using (
    organization_id = current_organization_id()
    and (is_member() or is_admin())
  );

create policy members_select on members for select to authenticated
  using (
    organization_id = current_organization_id()
    and (id = auth.uid() or is_admin())
  );

create policy admins_select on admins for select to authenticated
  using (organization_id = current_organization_id() and is_admin());

create policy categories_select on categories for select to authenticated
  using (
    organization_id = current_organization_id()
    and contest_id = current_contest_id()
    and ((active and is_member()) or is_admin())
  );

create policy submissions_select on submissions for select to authenticated
  using (
    organization_id = current_organization_id()
    and ((member_id = auth.uid() and is_member()) or is_admin())
  );

create policy audit_log_select on audit_log for select to authenticated
  using (organization_id = current_organization_id() and is_admin());

-- Proof paths begin with contest_id/member_id. Keep the same tenant boundary in Storage RLS.
drop policy if exists proofs_select on storage.objects;
create policy proofs_select on storage.objects for select to authenticated
  using (
    bucket_id = 'proofs'
    and exists (
      select 1
      from contests c
      where c.id::text = (storage.foldername(name))[1]
        and c.organization_id = current_organization_id()
        and (
          (c.id = current_contest_id()
            and (storage.foldername(name))[2] = auth.uid()::text
            and is_member())
          or is_admin()
        )
    )
  );
-- ----- 20261024163531_platform_owner_org_management.sql -----
-- Platform owners are not bound to one tenant. Their selected organisation is supplied as an
-- ordinary request header, but only an active platform_admins row can make that header effective.
create or replace function current_organization_id() returns uuid
language sql stable security definer set search_path = public, pg_temp as $$
  select case
    when exists (
      select 1 from platform_admins pa where pa.id = auth.uid() and pa.active
    ) then (
      select o.id
      from organizations o
      where o.id::text = (
        coalesce(current_setting('request.headers', true), '{}')::jsonb
          ->> 'x-organization-id'
      )
      limit 1
    )
    else coalesce(
      (select a.organization_id from admins a where a.id = auth.uid() and a.active),
      (select m.organization_id from members m where m.id = auth.uid() and m.active)
    )
  end
$$;

create or replace function is_org_admin(p_org_id uuid default current_organization_id()) returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select p_org_id = current_organization_id()
    and p_org_id is not null
    and (
      exists (select 1 from platform_admins pa where pa.id = auth.uid() and pa.active)
      or exists (
        select 1 from admins a
        where a.id = auth.uid() and a.active and a.organization_id = p_org_id
      )
    )
$$;

create or replace function is_org_owner(p_org_id uuid default current_organization_id()) returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select p_org_id = current_organization_id()
    and p_org_id is not null
    and (
      exists (select 1 from platform_admins pa where pa.id = auth.uid() and pa.active)
      or exists (
        select 1 from admins a
        where a.id = auth.uid() and a.active and a.role = 'owner'
          and a.organization_id = p_org_id
      )
    )
$$;

create or replace function is_admin() returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select current_organization_id() is not null and (
    exists (select 1 from platform_admins pa where pa.id = auth.uid() and pa.active)
    or exists (
      select 1 from admins a
      where a.id = auth.uid() and a.active
        and a.organization_id = current_organization_id()
    )
  )
$$;

create or replace function is_owner() returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select current_organization_id() is not null and (
    exists (select 1 from platform_admins pa where pa.id = auth.uid() and pa.active)
    or exists (
      select 1 from admins a
      where a.id = auth.uid() and a.active and a.role = 'owner'
        and a.organization_id = current_organization_id()
    )
  )
$$;

create function platform_owner_create_organization(
  p_name text,
  p_slug text,
  p_contest_name text,
  p_start_at timestamptz,
  p_end_at timestamptz
)
returns table (organization_id uuid, contest_id uuid)
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_name text := btrim(coalesce(p_name, ''));
  v_slug text := lower(btrim(coalesce(p_slug, '')));
  v_contest_name text := btrim(coalesce(p_contest_name, ''));
  v_org_id uuid;
  v_contest_id uuid;
begin
  if not exists (select 1 from platform_admins pa where pa.id = auth.uid() and pa.active) then
    raise exception 'forbidden: Only a platform owner can create organisations.' using errcode = '42501';
  end if;
  perform _audit_ctx(null, null);
  if char_length(v_name) not between 1 and 120 then
    raise exception 'invalid_organization: Organisation name must be 1 to 120 characters.';
  end if;
  if char_length(v_slug) not between 2 and 60 or v_slug !~ '^[a-z0-9]+(-[a-z0-9]+)*$' then
    raise exception 'invalid_slug: Use 2 to 60 lowercase letters, numbers, and single hyphens.';
  end if;
  if char_length(v_contest_name) not between 1 and 120 then
    raise exception 'invalid_contest: Contest name must be 1 to 120 characters.';
  end if;
  if p_start_at is null or p_end_at is null or p_end_at <= p_start_at then
    raise exception 'invalid_dates: The contest end must be later than its start.';
  end if;

  begin
    insert into organizations (name, slug)
    values (v_name, v_slug)
    returning id into v_org_id;
  exception
    when unique_violation then
      raise exception 'organization_slug_taken: An organisation with this slug already exists.';
  end;

  insert into contests (organization_id, name, start_at, end_at)
  values (v_org_id, v_contest_name, p_start_at, p_end_at)
  returning id into v_contest_id;

  insert into categories (contest_id, name, points, reference_label, reference_hint, sort_order)
  values
    (v_contest_id, 'New Account', 2, 'Account username', 'jane_designs', 1),
    (v_contest_id, 'New Gig', 1, 'Gig title', 'i will build hubspot workflows', 2),
    (v_contest_id, 'New Message', 2, 'Buyer username + date', 'buyer123 2026-10-20', 3),
    (v_contest_id, 'Converted Message / Order', 5, 'Fiverr order number', 'FO1234567890', 4);

  insert into audit_log (contest_id, actor_type, actor_id, action, entity, entity_id, after)
  values (
    v_contest_id, 'admin', auth.uid(), 'organization.created', 'organization', v_org_id,
    jsonb_build_object('name', v_name, 'slug', v_slug)
  );

  return query select v_org_id, v_contest_id;
end $$;

revoke all on function platform_owner_create_organization(text, text, text, timestamptz, timestamptz)
  from public, anon, authenticated;
grant execute on function platform_owner_create_organization(text, text, text, timestamptz, timestamptz)
  to authenticated;
-- ----- 20261025064413_end_contest_early.sql -----
-- Allow an owner to close registration and submissions before the scheduled deadline.
alter table contests add column ended_at timestamptz;

create or replace function contest_effective_status(p_contest uuid) returns contest_status
language sql stable security definer set search_path = public, pg_temp as $$
  select case
    when c.manual_status in ('final', 'archived') then c.manual_status
    when c.ended_at is not null then 'closed'::contest_status
    when now() < c.start_at then 'setup'::contest_status
    when now() < c.end_at then 'open'::contest_status
    else 'closed'::contest_status
  end
  from contests c where c.id = p_contest
$$;

create function end_contest(p_reason text) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_id uuid := current_contest_id();
  v_reason text;
begin
  perform _require_owner();
  v_reason := _require_reason(p_reason);
  perform 1 from contests where id = v_id for update;
  if not found then
    raise exception 'not_found: Contest not found.';
  end if;
  if contest_effective_status(v_id) not in ('setup', 'open') then
    raise exception 'contest_not_active: The contest is already closed.';
  end if;

  perform _audit_ctx('contest.ended_early', v_reason);
  update contests set ended_at = now() where id = v_id;
end $$;

create or replace function extend_deadline(p_new_end timestamptz, p_reason text) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_id uuid := current_contest_id();
  v_reason text;
begin
  perform _require_owner();
  v_reason := _require_reason(p_reason);
  if contest_effective_status(v_id) in ('final', 'archived') then
    raise exception 'contest_frozen: Reopen the contest before extending the deadline.';
  end if;
  if p_new_end <= (select end_at from contests where id = v_id) then
    raise exception 'deadline_shorten: The new deadline must be later than the current one.';
  end if;
  perform _audit_ctx('contest.deadline_extended', v_reason);
  update contests set end_at = p_new_end, ended_at = null where id = v_id;
end $$;

create or replace function publish_final(p_reason text) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_id uuid := current_contest_id();
  v_c contests;
  v_reason text;
begin
  perform _require_owner();
  v_reason := _require_reason(p_reason);
  select * into v_c from contests where id = v_id for update;
  if contest_effective_status(v_id) <> 'closed' then
    raise exception 'not_closed: The contest must be closed before publishing final results.';
  end if;
  if v_c.ended_at is null
     and now() <= v_c.end_at + make_interval(mins => v_c.grace_minutes) then
    raise exception 'grace_open: Wait until the grace period after the deadline has ended.';
  end if;
  if exists (select 1 from submissions where contest_id = v_id and status = 'pending') then
    raise exception 'pending_remaining: Review all pending submissions first.';
  end if;
  perform _audit_ctx('contest.published', v_reason);
  update contests
     set manual_status = 'final', finalized_at = now(),
         results_updated_at = case when finalized_at is not null then now() end
   where id = v_id;
end $$;

revoke all on function end_contest(text) from public, anon;
grant execute on function end_contest(text) to authenticated, service_role;
-- ----- 20261025070355_organization_next_contest.sql -----
-- Start a new contest within an organisation while retaining the previous results for seven days
-- after the new contest starts. Returning members keep the same Auth ID and password.

create table if not exists contest_history (
  source_contest_id uuid primary key,
  organization_id uuid not null references organizations (id),
  contest_name text not null,
  available_at timestamptz not null,
  expires_at timestamptz not null,
  categories jsonb not null,
  standings jsonb not null,
  created_at timestamptz not null default now(),
  check (expires_at > available_at)
);

create table if not exists organization_members (
  id            uuid primary key references auth.users (id),
  organization_id uuid not null references organizations (id),
  email         citext not null,
  display_name  text not null check (char_length(btrim(display_name)) between 1 and 60),
  title         text check (title is null or char_length(btrim(title)) between 1 and 80),
  key_version   int not null default 1,
  active        boolean not null default true,
  registered_at timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  unique (organization_id, email),
  unique (id, organization_id)
);
create index if not exists organization_members_org_active_idx on organization_members (organization_id, active);

insert into organization_members (
  id, organization_id, email, display_name, title, key_version, active, registered_at, updated_at
)
select id, organization_id, email, display_name, title, key_version, active, registered_at, updated_at
from members
on conflict (id) do nothing;

drop trigger if exists organization_members_touch on organization_members;
create trigger organization_members_touch before update on organization_members
  for each row execute function trg_touch_updated_at();

alter table organization_members enable row level security;
revoke all on organization_members from public, anon, authenticated;
revoke all on organization_members from service_role;
grant select, update on organization_members to service_role;

create index if not exists contest_history_expiry_idx on contest_history (expires_at);
alter table contest_history enable row level security;
revoke all on contest_history from public, anon, authenticated;
grant select on contest_history to service_role;

create or replace function trg_guard_category() returns trigger
language plpgsql set search_path = public, pg_temp as $$
declare
  v_contest uuid := coalesce(new.contest_id, old.contest_id);
  v_status contest_status := contest_effective_status(v_contest);
begin
  if tg_op = 'DELETE'
     and current_user = 'postgres'
     and current_setting('app.contest_retention_purge', true) = 'on' then
    return old;
  end if;
  if v_status in ('final', 'archived') then
    raise exception 'contest_frozen: The contest is final; categories cannot change.';
  end if;
  if tg_op = 'UPDATE' and new.points <> old.points
     and v_status <> 'setup'
     and not (select points_unlocked from contests where id = v_contest) then
    raise exception 'points_locked: Point values are locked once the contest starts.';
  end if;
  if tg_op = 'DELETE' then
    if exists (select 1 from submissions where category_id = old.id) then
      raise exception 'category_in_use: Category has submissions; deactivate it instead.';
    end if;
    return old;
  end if;
  return new;
end $$;

create or replace function trg_guard_submission() returns trigger
language plpgsql set search_path = public, pg_temp as $$
declare
  v_contest uuid := coalesce(new.contest_id, old.contest_id);
begin
  if tg_op = 'DELETE'
     and current_user = 'postgres'
     and current_setting('app.contest_retention_purge', true) = 'on' then
    return old;
  end if;
  if contest_effective_status(v_contest) in ('final', 'archived')
     and not (tg_op = 'DELETE' and old.status = 'draft') then
    raise exception 'contest_frozen: The contest is final; submissions cannot change.';
  end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end $$;

create or replace function trg_audit() returns trigger
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_old jsonb := case when tg_op in ('UPDATE', 'DELETE') then to_jsonb(old) end;
  v_new jsonb := case when tg_op in ('INSERT', 'UPDATE') then to_jsonb(new) end;
  v_row jsonb := coalesce(v_new, v_old);
  v_uid uuid := auth.uid();
  v_actor actor_type;
  v_noun text;
  v_action text;
  v_contest uuid;
begin
  if tg_table_name = 'contests'
     and tg_op = 'DELETE'
     and current_user = 'postgres'
     and current_setting('app.contest_retention_purge', true) = 'on' then
    return null;
  end if;
  if tg_table_name = 'submissions' then
    if coalesce(v_old ->> 'status', 'draft') = 'draft' and coalesce(v_new ->> 'status', 'draft') = 'draft' then
      return null;
    end if;
    if tg_op = 'UPDATE' and (v_old - 'claimed_by' - 'claimed_until') = (v_new - 'claimed_by' - 'claimed_until') then
      return null;
    end if;
  end if;
  if tg_op = 'UPDATE' and v_old = v_new then return null; end if;

  v_actor := case
    when v_uid is null then 'system'
    when exists (select 1 from admins where id = v_uid) then 'admin'
    when exists (select 1 from members where id = v_uid) then 'member'
    else 'system' end;
  v_noun := case tg_table_name
    when 'contests' then 'contest' when 'members' then 'member' when 'admins' then 'admin'
    when 'categories' then 'category' else 'submission' end;
  v_action := coalesce(
    nullif(current_setting('app.action', true), ''),
    case when tg_table_name = 'submissions' and tg_op = 'UPDATE' and v_old ->> 'status' <> v_new ->> 'status'
         then 'submission.' || (v_new ->> 'status') end,
    v_noun || '.' || lower(tg_op));
  v_contest := case tg_table_name
    when 'contests' then (v_row ->> 'id')::uuid
    when 'admins' then current_contest_id()
    else (v_row ->> 'contest_id')::uuid end;

  insert into audit_log (contest_id, actor_type, actor_id, action, entity, entity_id, before, after, reason)
  values (v_contest, v_actor, v_uid, v_action, tg_table_name, (v_row ->> 'id')::uuid,
          v_old, v_new, nullif(current_setting('app.reason', true), ''));
  return null;
end $$;

create or replace function trg_audit_immutable() returns trigger
language plpgsql as $$
begin
  if current_user = 'postgres'
     and current_setting('app.contest_retention_purge', true) = 'on' then
    return old;
  end if;
  raise exception 'audit_immutable: The audit log is append-only.';
end $$;

create or replace function enforce_identity_organization() returns trigger
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_organization_id uuid;
begin
  if tg_table_name = 'members' then
    select a.organization_id into v_organization_id from admins a where a.id = new.id;
    if v_organization_id is null then
      select om.organization_id into v_organization_id from organization_members om where om.id = new.id;
    end if;
  elsif tg_table_name = 'organization_members' then
    select a.organization_id into v_organization_id from admins a where a.id = new.id;
    if v_organization_id is null then
      select m.organization_id into v_organization_id from members m where m.id = new.id;
    end if;
  else
    select m.organization_id into v_organization_id from members m where m.id = new.id;
    if v_organization_id is null then
      select om.organization_id into v_organization_id from organization_members om where om.id = new.id;
    end if;
  end if;

  if v_organization_id is not null and v_organization_id <> new.organization_id then
    raise exception 'identity_organization_conflict: An Auth account can belong to only one organisation.';
  end if;
  return new;
end $$;

drop trigger if exists organization_members_validate_identity_organization on organization_members;
create trigger organization_members_validate_identity_organization
before insert or update of id, organization_id on organization_members
for each row execute function enforce_identity_organization();

revoke all on function enforce_identity_organization() from public, anon, authenticated;

create or replace function set_member_active(p_member uuid, p_active boolean) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare v_n int;
begin
  perform _require_admin();
  perform _audit_ctx(case when p_active then 'member.reactivated' else 'member.deactivated' end, null);
  update members set active = p_active where id = p_member and contest_id = current_contest_id();
  get diagnostics v_n = row_count;
  if v_n = 0 then raise exception 'not_found: Member not found.'; end if;
  update organization_members set active = p_active
  where id = p_member and organization_id = current_organization_id();
end $$;

create or replace function register_organization_member(
  p_organization_id uuid,
  p_member_id uuid,
  p_email citext,
  p_display_name text,
  p_title text
) returns table (id uuid, email citext, display_name text, title text, key_version int, active boolean)
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_contest_id uuid;
  v_status contest_status;
  v_display_name text;
  v_suffix int := 1;
begin
  if coalesce(auth.jwt() ->> 'role', '') <> 'service_role' then
    raise exception 'forbidden: Service role only.' using errcode = '42501';
  end if;
  if p_organization_id is null or not exists (
    select 1 from organizations where organizations.id = p_organization_id
  ) then
    raise exception 'organization_not_found: The selected organisation does not exist.';
  end if;
  if p_email is null or p_display_name is null
     or char_length(btrim(p_display_name)) not between 1 and 60 then
    raise exception 'invalid_member: Email and display name are required.';
  end if;
  if exists (select 1 from admins where admins.email = p_email) then
    raise exception 'admin_email: This email belongs to an admin and cannot register as a member.';
  end if;

  perform 1 from organizations where organizations.id = p_organization_id for update;
  v_display_name := left(btrim(p_display_name), 60);
  while exists (
    select 1 from organization_members om
    where om.organization_id = p_organization_id
      and lower(om.display_name) = lower(v_display_name)
  ) loop
    v_suffix := v_suffix + 1;
    v_display_name := left(btrim(p_display_name), 60 - char_length(' ' || v_suffix)) || ' ' || v_suffix;
  end loop;

  insert into organization_members (id, organization_id, email, display_name, title)
  values (p_member_id, p_organization_id, p_email, v_display_name, nullif(btrim(p_title), ''));

  select c.id
    into v_contest_id
  from contests c
  where c.organization_id = p_organization_id
  order by c.created_at desc
  limit 1
  for update;
  if v_contest_id is not null then
    v_status := contest_effective_status(v_contest_id);
  end if;

  if v_contest_id is not null and v_status in ('setup', 'open') then
    insert into members (id, contest_id, organization_id, email, display_name, title)
    values (p_member_id, v_contest_id, p_organization_id, p_email, v_display_name, nullif(btrim(p_title), ''));
  end if;

  return query select om.id, om.email, om.display_name, om.title, om.key_version, om.active
  from organization_members om where om.id = p_member_id;
end $$;

create or replace function create_next_contest(
  p_name text,
  p_start_at timestamptz,
  p_end_at timestamptz,
  p_reason text
) returns uuid
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_org uuid := current_organization_id();
  v_old_id uuid;
  v_new_id uuid;
  v_old contests;
  v_available_at timestamptz;
  v_reason text;
  v_categories jsonb;
  v_standings jsonb;
  v_roster record;
  v_display_name text;
  v_suffix int;
begin
  perform _require_owner();
  if v_org is null then
    raise exception 'forbidden: Owner only.' using errcode = '42501';
  end if;
  if p_name is null or char_length(btrim(p_name)) not between 1 and 120 then
    raise exception 'invalid_name: Contest name must be between 1 and 120 characters.';
  end if;
  if p_start_at is null or p_end_at is null or p_end_at <= p_start_at then
    raise exception 'invalid_dates: The end date must be after the start date.';
  end if;
  v_reason := _require_reason(p_reason);

  -- Serialize starts for this organisation so concurrent owner requests cannot create two contests.
  perform 1 from organizations where id = v_org for update;
  v_old_id := current_contest_id();
  if v_old_id is null then
    raise exception 'contest_not_found: No contest exists for this organisation.';
  end if;
  select * into v_old from contests where id = v_old_id and organization_id = v_org for update;
  if not found or contest_effective_status(v_old_id) not in ('final', 'archived') then
    raise exception 'contest_not_final: Publish final results before starting another contest.';
  end if;
  if exists (
    select 1 from contests c
    where c.organization_id = v_org
      and c.id <> v_old_id
      and contest_effective_status(c.id) not in ('final', 'archived')
  ) then
    raise exception 'contest_in_progress: Finish the current contest before starting another.';
  end if;

  select coalesce(jsonb_agg(to_jsonb(cat) order by cat.sort_order, cat.id), '[]'::jsonb)
    into v_categories
  from categories cat where cat.contest_id = v_old_id;
  select coalesce(jsonb_agg(to_jsonb(st) order by st.ord), '[]'::jsonb)
    into v_standings
  from _standings(v_old_id) st;

  v_available_at := greatest(p_start_at, now());
  insert into contest_history (
    source_contest_id, organization_id, contest_name, available_at, expires_at, categories, standings
  ) values (
    v_old_id, v_org, v_old.name, v_available_at, v_available_at + interval '7 days',
    v_categories, v_standings
  );

  insert into contests (organization_id, name, start_at, end_at)
  values (v_org, btrim(p_name), p_start_at, p_end_at)
  returning id into v_new_id;

  insert into categories (contest_id, name, points, reference_label, reference_hint, sort_order)
  values
    (v_new_id, 'New Account', 2, 'Account username', 'jane_designs', 1),
    (v_new_id, 'New Gig', 1, 'Gig title', 'i will build hubspot workflows', 2),
    (v_new_id, 'New Message', 2, 'Buyer username + date', 'buyer123 2026-10-20', 3),
    (v_new_id, 'Converted Message / Order', 5, 'Fiverr order number', 'FO1234567890', 4);

  perform set_config('app.action', 'contest.superseded_cleanup', true);
  perform set_config('app.reason', v_reason, true);
  perform set_config('app.contest_retention_purge', 'on', true);
  delete from submissions where contest_id = v_old_id;
  delete from categories where contest_id = v_old_id;
  update contests set manual_status = 'archived' where id = v_old_id;
  update members set contest_id = v_new_id where contest_id = v_old_id;
  for v_roster in
    select om.* from organization_members om
    where om.organization_id = v_org
      and not exists (select 1 from members m where m.id = om.id)
    order by om.registered_at, om.id
  loop
    v_display_name := v_roster.display_name;
    v_suffix := 1;
    while exists (
      select 1 from members m
      where m.contest_id = v_new_id and lower(m.display_name) = lower(v_display_name)
    ) loop
      v_suffix := v_suffix + 1;
      v_display_name := left(v_roster.display_name, 60 - char_length(' ' || v_suffix)) || ' ' || v_suffix;
    end loop;

    update organization_members set display_name = v_display_name where id = v_roster.id;
    insert into members (
      id, contest_id, organization_id, email, display_name, title, key_version, active, registered_at
    ) values (
      v_roster.id, v_new_id, v_roster.organization_id, v_roster.email, v_display_name, v_roster.title,
      v_roster.key_version, v_roster.active, v_roster.registered_at
    );
  end loop;
  perform set_config('app.contest_retention_purge', 'off', true);

  return v_new_id;
end $$;

create or replace function purge_expired_contest_history(p_source_contest_ids uuid[])
returns int
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_count int;
begin
  if coalesce(auth.jwt() ->> 'role', '') <> 'service_role' then
    raise exception 'forbidden: Service role only.' using errcode = '42501';
  end if;
  if p_source_contest_ids is null or cardinality(p_source_contest_ids) = 0 then
    return 0;
  end if;
  if exists (
    select 1 from unnest(p_source_contest_ids) as requested(id)
    left join contest_history h on h.source_contest_id = requested.id
    where h.source_contest_id is null or h.expires_at > now()
  ) then
    raise exception 'history_not_expired: Contest history is not ready for deletion.';
  end if;

  perform set_config('app.contest_retention_purge', 'on', true);
  delete from audit_log where contest_id = any(p_source_contest_ids);
  delete from contests where id = any(p_source_contest_ids) and manual_status = 'archived';
  delete from contest_history where source_contest_id = any(p_source_contest_ids);
  get diagnostics v_count = row_count;
  perform set_config('app.contest_retention_purge', 'off', true);
  return v_count;
end $$;

create or replace function get_contest_history()
returns table (
  source_contest_id uuid,
  contest_name text,
  available_at timestamptz,
  expires_at timestamptz,
  categories jsonb,
  standings jsonb
)
language plpgsql stable security definer set search_path = public, pg_temp as $$
begin
  perform _require_owner();
  return query
    select h.source_contest_id, h.contest_name, h.available_at, h.expires_at, h.categories, h.standings
    from contest_history h
    where h.organization_id = current_organization_id()
      and h.available_at <= now()
      and h.expires_at > now()
    order by h.created_at desc;
end $$;

revoke all on function create_next_contest(text, timestamptz, timestamptz, text) from public, anon, authenticated;
revoke all on function get_contest_history() from public, anon, authenticated;
revoke all on function purge_expired_contest_history(uuid[]) from public, anon, authenticated, service_role;
revoke all on function register_organization_member(uuid, uuid, citext, text, text) from public, anon, authenticated, service_role;
grant execute on function create_next_contest(text, timestamptz, timestamptz, text) to authenticated;
grant execute on function get_contest_history() to authenticated;
grant execute on function purge_expired_contest_history(uuid[]) to service_role;
grant execute on function register_organization_member(uuid, uuid, citext, text, text) to service_role;
-- ----- 20261026093834_all_organization_leaderboards.sql -----
-- Admins can compare live leaderboards across organisations. The selected/own organisation
-- is returned first; the participant data remains limited to public leaderboard fields.
create function get_running_organization_leaderboards()
returns table (
  organization_id uuid,
  organization_name text,
  is_current_organization boolean,
  contest_id uuid,
  contest_name text,
  start_at timestamptz,
  end_at timestamptz,
  categories jsonb,
  member_id uuid,
  display_name text,
  points int,
  tasks_completed int,
  rank int,
  is_me boolean,
  category_counts jsonb,
  member_order int
)
language plpgsql stable security definer set search_path = public, pg_temp as $$
#variable_conflict use_column
begin
  if not is_admin() then
    raise exception 'forbidden: Admins only.' using errcode = '42501';
  end if;

  return query
  with running_contests as (
    select o.id as organization_id,
           o.name as organization_name,
           (o.id = current_organization_id()) as is_current_organization,
           c.id as contest_id,
           c.name as contest_name,
           c.start_at,
           c.end_at
    from organizations o
    join lateral (
      select current_contest.*
      from contests current_contest
      where current_contest.organization_id = o.id
      order by current_contest.created_at desc
      limit 1
    ) c on true
    where contest_effective_status(c.id) = 'open'
  )
  select rc.organization_id,
         rc.organization_name,
         rc.is_current_organization,
         rc.contest_id,
         rc.contest_name,
         rc.start_at,
         rc.end_at,
         coalesce(category_list.categories, '[]'::jsonb),
         st.member_id,
         st.display_name,
         st.points,
         st.tasks_completed,
         st.rank,
         coalesce(st.member_id = auth.uid(), false),
         coalesce(st.category_counts, '{}'::jsonb),
         st.ord
  from running_contests rc
  left join lateral (
    select jsonb_agg(
      jsonb_build_object(
        'id', c.id,
        'name', c.name,
        'points', c.points,
        'reference_label', c.reference_label,
        'reference_hint', c.reference_hint,
        'active', c.active,
        'sort_order', c.sort_order
      ) order by c.sort_order
    ) as categories
    from categories c
    where c.contest_id = rc.contest_id and c.active
  ) category_list on true
  left join lateral (
    select standings.*
    from _standings(rc.contest_id) standings
    where standings.active
    order by standings.ord
  ) st on true
  order by rc.is_current_organization desc, lower(rc.organization_name), st.ord nulls last;
end $$;

revoke all on function get_running_organization_leaderboards() from public, anon, authenticated;
grant execute on function get_running_organization_leaderboards() to authenticated, service_role;
